//! Arena-backed nodes for the circular doubly linked lists used by the
//! triangulator.
//!
//! The reference implementation threads raw pointers between heap allocated
//! nodes. Rust models the exact same topology with indices into a single
//! `Vec<Node>` arena; `NIL` plays the role of the null pointer. Node identity
//! (pointer comparison in C++) becomes index comparison here, which is
//! equivalent because nodes are never moved or reused once constructed.

/// Sentinel standing in for a null node pointer.
pub const NIL: usize = usize::MAX;

#[derive(Clone, Copy, Debug)]
pub struct Node {
    /// Index of the vertex in the flattened input coordinate sequence.
    pub i: u32,
    pub x: f64,
    pub y: f64,

    /// Previous and next vertex nodes in the polygon ring.
    pub prev: usize,
    pub next: usize,

    /// z-order curve value.
    pub z: i32,

    /// Previous and next nodes in the z-order linked list.
    pub prev_z: usize,
    pub next_z: usize,

    /// Indicates whether this is a steiner point.
    pub steiner: bool,
}

impl Node {
    pub fn new(i: u32, x: f64, y: f64) -> Node {
        Node {
            i,
            x,
            y,
            prev: NIL,
            next: NIL,
            z: 0,
            prev_z: NIL,
            next_z: NIL,
            steiner: false,
        }
    }
}

/// Growable pool of nodes. Nodes are stable for the lifetime of one
/// triangulation, so an index is a permanent handle.
pub struct Arena {
    nodes: Vec<Node>,
}

impl Arena {
    pub fn new() -> Arena {
        Arena { nodes: Vec::new() }
    }

    pub fn reserve(&mut self, additional: usize) {
        self.nodes.reserve(additional);
    }

    pub fn clear(&mut self) {
        self.nodes.clear();
    }

    /// Allocates a node and returns its handle.
    pub fn create(&mut self, i: u32, x: f64, y: f64) -> usize {
        self.nodes.push(Node::new(i, x, y));
        self.nodes.len() - 1
    }

    pub fn as_slice(&self) -> &[Node] {
        &self.nodes
    }
}

impl std::ops::Index<usize> for Arena {
    type Output = Node;

    fn index(&self, index: usize) -> &Node {
        &self.nodes[index]
    }
}

impl std::ops::IndexMut<usize> for Arena {
    fn index_mut(&mut self, index: usize) -> &mut Node {
        &mut self.nodes[index]
    }
}

