//! Geometric predicates.
//!
//! Every expression here mirrors the operand order of the C++ original so the
//! floating point rounding is bit-for-bit identical: `a * b - c * d` is not
//! reassociated, and comparisons keep the same strict/non-strict boundaries.

use super::node::Node;

/// Signed double area of the triangle `p q r` (negative when counter-clockwise
/// in the reference's coordinate convention).
pub fn area(nodes: &[Node], p: usize, q: usize, r: usize) -> f64 {
    let (p, q, r) = (&nodes[p], &nodes[q], &nodes[r]);
    (q.y - p.y) * (r.x - q.x) - (q.x - p.x) * (r.y - q.y)
}

/// Exact coordinate equality of two nodes.
pub fn equals(nodes: &[Node], p1: usize, p2: usize) -> bool {
    nodes[p1].x == nodes[p2].x && nodes[p1].y == nodes[p2].y
}

/// Checks whether a point lies inside a triangle, boundary included.
#[allow(clippy::too_many_arguments)]
pub fn point_in_triangle(
    ax: f64,
    ay: f64,
    bx: f64,
    by: f64,
    cx: f64,
    cy: f64,
    px: f64,
    py: f64,
) -> bool {
    (cx - px) * (ay - py) - (ax - px) * (cy - py) >= 0.0
        && (ax - px) * (by - py) - (bx - px) * (ay - py) >= 0.0
        && (bx - px) * (cy - py) - (cx - px) * (by - py) >= 0.0
}

pub fn sign(val: f64) -> i32 {
    if val > 0.0 {
        1
    } else if val < 0.0 {
        -1
    } else {
        0
    }
}

/// For collinear points `p`, `q`, `r`, checks if `q` lies on segment `pr`.
pub fn on_segment(nodes: &[Node], p: usize, q: usize, r: usize) -> bool {
    let (p, q, r) = (&nodes[p], &nodes[q], &nodes[r]);
    q.x <= p.x.max(r.x) && q.x >= p.x.min(r.x) && q.y <= p.y.max(r.y) && q.y >= p.y.min(r.y)
}

/// Checks if two segments `p1q1` and `p2q2` intersect.
pub fn intersects(nodes: &[Node], p1: usize, q1: usize, p2: usize, q2: usize) -> bool {
    let o1 = sign(area(nodes, p1, q1, p2));
    let o2 = sign(area(nodes, p1, q1, q2));
    let o3 = sign(area(nodes, p2, q2, p1));
    let o4 = sign(area(nodes, p2, q2, q1));

    if o1 != o2 && o3 != o4 {
        return true; // general case
    }

    // p1, q1 and p2 are collinear and p2 lies on p1q1
    if o1 == 0 && on_segment(nodes, p1, p2, q1) {
        return true;
    }
    // p1, q1 and q2 are collinear and q2 lies on p1q1
    if o2 == 0 && on_segment(nodes, p1, q2, q1) {
        return true;
    }
    // p2, q2 and p1 are collinear and p1 lies on p2q2
    if o3 == 0 && on_segment(nodes, p2, p1, q2) {
        return true;
    }
    // p2, q2 and q1 are collinear and q1 lies on p2q2
    if o4 == 0 && on_segment(nodes, p2, q1, q2) {
        return true;
    }

    false
}

/// Checks if a polygon diagonal `ab` is locally inside the polygon at `a`.
pub fn locally_inside(nodes: &[Node], a: usize, b: usize) -> bool {
    let (a_prev, a_next) = (nodes[a].prev, nodes[a].next);
    if area(nodes, a_prev, a, a_next) < 0.0 {
        area(nodes, a, b, a_next) >= 0.0 && area(nodes, a, a_prev, b) >= 0.0
    } else {
        area(nodes, a, b, a_prev) < 0.0 || area(nodes, a, a_next, b) < 0.0
    }
}

/// Checks if the middle of the segment `ab` is inside the polygon.
pub fn middle_inside(nodes: &[Node], a: usize, b: usize) -> bool {
    let mut p = a;
    let mut inside = false;
    let px = (nodes[a].x + nodes[b].x) / 2.0;
    let py = (nodes[a].y + nodes[b].y) / 2.0;
    loop {
        let n = nodes[p].next;
        let (pn, nn) = (&nodes[p], &nodes[n]);
        if ((pn.y > py) != (nn.y > py))
            && nn.y != pn.y
            && (px < (nn.x - pn.x) * (py - pn.y) / (nn.y - pn.y) + pn.x)
        {
            inside = !inside;
        }
        p = n;
        if p == a {
            break;
        }
    }

    inside
}

/// Whether sector defined by node `m` contains sector defined by node `p`.
pub fn sector_contains_sector(nodes: &[Node], m: usize, p: usize) -> bool {
    area(nodes, nodes[m].prev, m, nodes[p].prev) < 0.0
        && area(nodes, nodes[p].next, m, nodes[m].next) < 0.0
}

